export interface AsamAlertSlots {
    default?: () => unknown;
    title?: () => unknown;
    icon?: () => unknown;
}

export interface AsamApiPageSource<Q, P, R, T extends object> {
    readonly api: AsamApiRequest<P, R>;
    readonly query: Q;
    readonly buildPageParams: (query: Q, page: AsamPageRequest) => P;
    readonly transform: (response: R) => AsamPage<T>;
}

export type AsamApiSelectSearch<P> = AsamRemoteSearchBase & {
    readonly buildParams: (params: P, text: string) => P;
    readonly buildRequest?: never;
};

export interface AsamAsyncChoiceEmits<V extends AsamValue = AsamValue, I extends object = object> {
    'update:modelValue': [
        value: V | AsamOption<V, I> | readonly V[] | readonly AsamOption<V, I>[] | string | null
    ];
    change: [
        value: V | AsamOption<V, I> | readonly V[] | readonly AsamOption<V, I>[] | string | null
    ];
    success: [data: readonly AsamOption<V, I>[]];
    error: [error: AsamDataError];
}

export interface AsamAsyncChoiceExpose<V extends AsamValue = AsamValue, I extends object = AsamRecord> {
    reload(options?: {
        readonly force?: boolean;
    }): Promise<AsamReloadResult<readonly AsamOption<V, I>[]>>;
    cancel(): void;
}

export interface AsamAsyncChoiceSlots<V extends AsamValue = AsamValue, I extends object = object> extends AsamDataErrorSlots<readonly AsamOption<V, I>[]> {
    default?: () => unknown;
    option?: (scope: {
        option: AsamOption<V, I>;
    }) => unknown;
}

export interface AsamAsyncSelectEmits {
    'update:modelValue': [value: AsamSelectAnyModelValue];
    change: [value: AsamSelectAnyModelValue];
    clear: [];
    focus: [event: FocusEvent];
    blur: [event: FocusEvent];
    'visible-change': [visible: boolean];
    'remove-tag': [value: unknown];
    'popup-scroll': [event: {
        scrollTop: number;
        scrollLeft: number;
    }];
    'end-reached': AsamSelectEmits['end-reached'];
    success: [data: readonly AsamOption<AsamValue, object>[]];
    error: [error: AsamDataError];
}

export interface AsamAsyncSelectExpose<V extends AsamValue = AsamValue, I extends object = AsamRecord> extends AsamSelectExpose {
    readonly selectedLabel: string | string[];
    reload(options?: {
        readonly force?: boolean;
    }): Promise<AsamReloadResult<readonly AsamOption<V, I>[]>>;
    cancel(): void;
}

export interface AsamAsyncSelectSlots<V extends AsamValue = AsamValue, I extends object = object> extends AsamDataErrorSlots<readonly AsamOption<V, I>[]> {
    default?: () => unknown;
    prefix?: () => unknown;
    header?: () => unknown;
    footer?: () => unknown;
    empty?: () => unknown;
    loading?: () => unknown;
    tag?: AsamSelectSlots['tag'];
    label?: AsamSelectSlots['label'];
}

export interface AsamAutocompleteEmits<V extends AsamValue = AsamValue, I extends object = object, T extends object = AsamOption<V, I>> {
    'update:modelValue': [value: string | number];
    input: [value: string | number];
    change: [value: string | number];
    /** Matched original suggestion, or the native unmatched Enter value-only payload. */
    select: [item: T | AsamOption<V, I> | {
        value: string | number;
    }];
    clear: [];
    focus: [event: FocusEvent];
    blur: [event: FocusEvent];
    compositionstart: [event: CompositionEvent];
    compositionupdate: [event: CompositionEvent];
    compositionend: [event: CompositionEvent];
    mouseenter: [event: MouseEvent];
    mouseleave: [event: MouseEvent];
    keydown: [event: KeyboardEvent | Event];
}

export interface AsamAutocompleteExpose<T extends object = AsamRecord> {
    readonly highlightedIndex: number;
    readonly activated: boolean;
    readonly loading: boolean;
    readonly inputRef: InputInstance | undefined;
    readonly popperRef: TooltipInstance | undefined;
    readonly suggestions: T[];
    focus(): void;
    blur(): void;
    close(): void;
    highlight(index: number): void;
    getData(query: string): Promise<void>;
    handleSelect(item: T): Promise<void>;
    handleKeyEnter(): Promise<void>;
}

export interface AsamAutocompleteProps<V extends AsamValue = AsamValue, I extends object = AsamRecord, T extends object = AsamOption<V, I>> {
    /** String or number input value. */
    readonly modelValue?: string | number;
    /** Native input bounds/step, beyond the upstream InputProps declaration. */
    readonly min?: InputHTMLAttributes['min'];
    readonly max?: InputHTMLAttributes['max'];
    readonly step?: InputHTMLAttributes['step'];
    /** ASAM static options, filtered by label and disabled state. */
    readonly options?: readonly AsamOption<V, I>[];
    /** Native suggestions take precedence over static options. */
    readonly fetchSuggestions?: AsamAutocompleteFetchSuggestions<T>;
    /** Maximum ASAM static/remote option suggestions. Native suggestions are not truncated. */
    readonly maxSuggestions?: number;
    /** Internal data-layer bridge preserving ASAM option objects. */
    readonly remoteSuggestions?: (query: string) => Promise<readonly AsamOption<V, I>[]>;
    /** Native id capability. */
    readonly id?: AutocompleteProps['id'];
    /** Explicit density; omission preserves inheritance. */
    readonly size?: AsamControlSize;
    /** Native disabled capability. */
    readonly disabled?: AutocompleteProps['disabled'];
    /** Native modelModifiers capability. */
    readonly modelModifiers?: AutocompleteProps['modelModifiers'];
    /** Native maxlength capability. */
    readonly maxlength?: AutocompleteProps['maxlength'];
    /** Native minlength capability. */
    readonly minlength?: AutocompleteProps['minlength'];
    /** Native type capability. */
    readonly type?: AutocompleteProps['type'];
    /** Native resize capability. */
    readonly resize?: AutocompleteProps['resize'];
    /** Native autosize capability. */
    readonly autosize?: AutocompleteProps['autosize'];
    /** Native autocomplete capability. */
    readonly autocomplete?: AutocompleteProps['autocomplete'];
    /** Native formatter capability. */
    readonly formatter?: AutocompleteProps['formatter'];
    /** Native parser capability. */
    readonly parser?: AutocompleteProps['parser'];
    /** Native placeholder capability. */
    readonly placeholder?: AutocompleteProps['placeholder'];
    /** Native form capability. */
    readonly form?: AutocompleteProps['form'];
    /** Native readonly capability. */
    readonly readonly?: AutocompleteProps['readonly'];
    /** Native clearable capability. */
    readonly clearable?: AutocompleteProps['clearable'];
    /** Native clearIcon capability. */
    readonly clearIcon?: AutocompleteProps['clearIcon'];
    /** Native showPassword capability. */
    readonly showPassword?: AutocompleteProps['showPassword'];
    /** Native showWordLimit capability. */
    readonly showWordLimit?: AutocompleteProps['showWordLimit'];
    /** Native wordLimitPosition capability. */
    readonly wordLimitPosition?: AutocompleteProps['wordLimitPosition'];
    /** Native suffixIcon capability. */
    readonly suffixIcon?: AutocompleteProps['suffixIcon'];
    /** Native prefixIcon capability. */
    readonly prefixIcon?: AutocompleteProps['prefixIcon'];
    /** Native containerRole capability. */
    readonly containerRole?: AutocompleteProps['containerRole'];
    /** Native tabindex capability. */
    readonly tabindex?: AutocompleteProps['tabindex'];
    /** Native validateEvent capability. */
    readonly validateEvent?: AutocompleteProps['validateEvent'];
    /** Native inputStyle capability. */
    readonly inputStyle?: AutocompleteProps['inputStyle'];
    /** Native autofocus capability. */
    readonly autofocus?: AutocompleteProps['autofocus'];
    /** Native rows capability. */
    readonly rows?: AutocompleteProps['rows'];
    /** Native ariaLabel capability. */
    readonly ariaLabel?: AutocompleteProps['ariaLabel'];
    /** Native inputmode capability. */
    readonly inputmode?: AutocompleteProps['inputmode'];
    /** Native name capability. */
    readonly name?: AutocompleteProps['name'];
    /** Native countGraphemes capability. */
    readonly countGraphemes?: AutocompleteProps['countGraphemes'];
    /** Native valueKey capability. */
    readonly valueKey?: AutocompleteProps['valueKey'];
    /** Native debounce capability. */
    readonly debounce?: AutocompleteProps['debounce'];
    /** Native placement capability. */
    readonly placement?: AutocompleteProps['placement'];
    /** Native popperClass capability. */
    readonly popperClass?: AutocompleteProps['popperClass'];
    /** Native popperStyle capability. */
    readonly popperStyle?: AutocompleteProps['popperStyle'];
    /** Popper positioning modifiers and options for the actual suggestions panel. */
    readonly popperOptions?: AutocompleteProps['popperOptions'];
    /** Display the suggestions panel arrow. Default: true. */
    readonly showArrow?: AutocompleteProps['showArrow'];
    /** Native triggerOnFocus capability. */
    readonly triggerOnFocus?: AutocompleteProps['triggerOnFocus'];
    /** Native selectWhenUnmatched capability. */
    readonly selectWhenUnmatched?: AutocompleteProps['selectWhenUnmatched'];
    /** Native hideLoading capability. */
    readonly hideLoading?: AutocompleteProps['hideLoading'];
    /** Native teleported capability. */
    readonly teleported?: AutocompleteProps['teleported'];
    /** Native appendTo capability. */
    readonly appendTo?: AutocompleteProps['appendTo'];
    /** Native highlightFirstItem capability. */
    readonly highlightFirstItem?: AutocompleteProps['highlightFirstItem'];
    /** Native fitInputWidth capability. */
    readonly fitInputWidth?: AutocompleteProps['fitInputWidth'];
    /** Native loopNavigation capability. */
    readonly loopNavigation?: AutocompleteProps['loopNavigation'];
}

export interface AsamAutocompleteSlots<V extends AsamValue = AsamValue, I extends object = object, T extends object = AsamOption<V, I>> {
    default?: (props: {
        item: T | AsamOption<V, I>;
    }) => unknown;
    prefix?: () => unknown;
    suffix?: () => unknown;
    prepend?: () => unknown;
    append?: () => unknown;
    header?: () => unknown;
    footer?: () => unknown;
    loading?: () => unknown;
}

export interface AsamAutoResizerSlots {
    default?: (scope: {
        height: number;
        width: number;
    }) => VNode[];
}

interface AvatarGroupContext {
  size?: AvatarProps['size'];
  shape?: AvatarProps['shape'];
}

export type AsamBaseFormEmits = {
    [K in keyof typeof formEmits]: Parameters<(typeof formEmits)[K]>;
};

export interface AsamButtonExpose {
    readonly ref: HTMLButtonElement | undefined;
    readonly size: AsamButtonSize;
    readonly type: AsamButtonType;
    readonly disabled: boolean;
    /** Live public native spacing state; caller default slot is delegated unchanged. */
    readonly shouldAddSpace: boolean;
}

export interface AsamButtonGroupProps {
    readonly size?: AsamControlSize;
    readonly type?: AsamButtonType;
    /** Lay out buttons horizontally or vertically. */
    readonly direction?: 'horizontal' | 'vertical';
}

export interface AsamButtonProps {
    /** Semantic color; explicit type overrides group and provider. Standalone default is secondary. */
    readonly type?: AsamButtonType;
    /** Explicit density; omission preserves inheritance. */
    readonly size?: AsamButtonSize;
    /** Component, registered component name or named icon; overridden by the icon slot. */
    readonly icon?: Component | string;
    /** Icon width and height in pixels. */
    readonly iconSize?: number;
    /** Position of the custom icon. */
    readonly iconPosition?: 'left' | 'right';
    /** Show loading content and suppress activation. */
    readonly loading?: boolean;
    /** Custom spinner, overridden by loading slot. */
    readonly loadingIcon?: ButtonProps['loadingIcon'];
    /** Disable interaction; omission preserves form inheritance. */
    readonly disabled?: boolean;
    /** Fill the available width. */
    readonly block?: boolean;
    /** Native button behavior. */
    readonly nativeType?: AsamButtonNativeType;
    /** Pointer and keyboard press feedback. */
    readonly pressAnimation?: boolean;
    /** Outline form of the semantic color. */
    readonly plain?: boolean;
    /** Backgroundless text form with hover background. */
    readonly text?: boolean;
    /** Inline link form. */
    readonly link?: boolean;
    /** Always show text-button background. */
    readonly bg?: boolean;
    /** Native autofocus. */
    readonly autofocus?: boolean;
    /** Pill-shaped border radius. */
    readonly round?: boolean;
    /** Equal width and height. */
    readonly circle?: boolean;
    /** Dashed border form. */
    readonly dashed?: boolean;
    /** Custom color with derived interactive colors. */
    readonly color?: string;
    /** Derive custom color for dark surfaces. */
    readonly dark?: boolean;
    /** Insert spacing between exactly two Chinese characters. */
    readonly autoInsertSpace?: boolean;
    /** Render a native tag or component. */
    readonly tag?: string | Component;
}

export interface AsamButtonSlots {
    default?: () => unknown;
    icon?: () => unknown;
    loading?: () => unknown;
}

export interface AsamCardListProps {
    columns?: number | null;
    minCardWidth?: AsamCssSize;
    maxCardWidth?: AsamCssSize;
    gap?: AsamCssSize;
    rowGap?: AsamCssSize;
    /** Horizontal item alignment, independent of vertical equal-height behavior. */
    align?: AsamCardListAlign;
    /** Stretch cards to the tallest card in each grid row; false keeps their natural height. */
    equalHeight?: boolean;
}

export interface AsamCardProps extends Omit<CardProps, 'bodyClass'> {
    title?: string;
    subtitle?: string;
    shadow?: 'always' | 'hover' | 'never';
    bordered?: boolean;
    hoverable?: boolean;
    bodyClass?: string | string[];
}

export interface AsamCardSlots {
    header?: () => unknown;
    extra?: () => unknown;
    default?: () => unknown;
    footer?: () => unknown;
}

type CarouselContext = {
  root: Ref<HTMLElement | undefined>;
  items: Ref<CarouselItemContext[]>;
  isCardType: Ref<boolean>;
  isVertical: Ref<boolean>;
  loop: boolean;
  cardScale: number;
  addItem: (item: CarouselItemContext) => void;
  removeItem: (item: CarouselItemContext) => void;
  setActiveItem: (index: number) => void;
  setContainerHeight: (height: number) => void;
};

type CarouselItemContext = {
  props: Required<CarouselItemProps>;
  states: CarouselItemStates;
  uid: number;
  getVnode: () => VNode;
  translateItem: (index: number, activeIndex: number, oldIndex?: number) => void;
};

type CarouselItemStates = {
  hover: boolean;
  translate: number;
  scale: number;
  active: boolean;
  ready: boolean;
  inStage: boolean;
  animating: boolean;
};

export interface AsamCascaderEmits {
    'update:modelValue': [value: AsamHierarchyModel | CascaderValue | undefined];
    change: [value: AsamHierarchyModel | CascaderValue | undefined];
    clear: [];
    focus: [event: FocusEvent];
    blur: [event: FocusEvent];
    visibleChange: Parameters<(typeof cascaderEmits)['visibleChange']>;
    expandChange: Parameters<(typeof cascaderEmits)['expandChange']>;
    removeTag: Parameters<(typeof cascaderEmits)['removeTag']>;
}

interface CascaderProps {
  expandTrigger?: ExpandTrigger;
  multiple?: boolean;
  checkStrictly?: boolean;
  emitPath?: boolean;
  lazy?: boolean;
  lazyLoad?: LazyLoad;
  value?: string;
  label?: string;
  children?: string;
  disabled?: string | isDisabled;
  leaf?: string | isLeaf;
  hoverThreshold?: number;
  checkOnClickNode?: boolean;
  checkOnClickLeaf?: boolean;
  showPrefix?: boolean;
}

export type AsamCascaderNativeValueProps = Omit<AsamCascaderNativeProps, 'size'> & AsamControlSizeProps & {
    valueMode: 'native';
    multipleValueMode?: never;
};

declare class Node {
  readonly data: CascaderOption;
  readonly config: CascaderConfig;
  readonly parent?: Node | undefined;
  readonly root: boolean;
  readonly uid: number;
  readonly level: number;
  readonly value: CascaderNodeValue;
  readonly label: string;
  readonly pathNodes: Node[];
  readonly pathValues: CascaderNodePathValue;
  readonly pathLabels: string[];
  childrenData: ChildrenData;
  children: Node[];
  text: string;
  loaded: boolean;
  /**
   * Is it checked
   *
   * @default false
   */
  checked: boolean;
  /**
   * Used to indicate the intermediate state of unchecked and fully checked child nodes
   *
   * @default false
   */
  indeterminate: boolean;
  /**
   * Loading Status
   *
   * @default false
   */
  loading: boolean;
  constructor(data: CascaderOption, config: CascaderConfig, parent?: Node | undefined, root?: boolean);
  get isDisabled(): boolean;
  get isLeaf(): boolean;
  get valueByOption(): CascaderNodeValue | CascaderNodePathValue;
  appendChild(childData: CascaderOption): Node;
  calcText(allLevels: boolean, separator: string): string;
  broadcast(checked: boolean): void;
  emit(): void;
  onParentCheck(checked: boolean): void;
  onChildCheck(): void;
  setCheckState(checked: boolean): void;
  doCheck(checked: boolean): void;
}

interface CascaderOption extends Record<string, unknown> {
  label?: string;
  value?: CascaderNodeValue;
  children?: CascaderOption[];
  disabled?: boolean;
  leaf?: boolean;
}

export type AsamCascaderPanelEmits = {
    [K in keyof typeof cascaderPanelEmits]: Parameters<(typeof cascaderPanelEmits)[K]>;
};

export interface AsamCascaderPanelSlots {
    default?: (scope: {
        node: CascaderNode;
        data: CascaderOption;
    }) => unknown;
    empty?: () => unknown;
}

export type AsamCascaderSelectionProps<V extends AsamValue = AsamValue, I extends object = object> = Omit<NonNullable<AsamCascaderNativeProps['props']>, 'lazyLoad'> & {
    readonly lazyLoad?: AsamCascaderLazyLoad<V, I>;
};

export interface AsamCascaderSlots {
    default?: (scope: {
        /** Present in normalized modes; native mode retains only the upstream slot fields. */
        option?: AsamHierarchyOption;
        data: CascaderOption;
        node: CascaderNode;
    }) => unknown;
    empty?: () => unknown;
    prefix?: () => unknown;
    header?: () => unknown;
    footer?: () => unknown;
    tag?: (scope: {
        data: CascaderTag[];
        deleteTag: (tag: CascaderTag) => void;
    }) => unknown;
    'suggestion-item'?: (scope: {
        item: CascaderNode;
    }) => unknown;
}

interface Tag {
  node?: Node;
  key: number;
  text: string;
  hitState?: boolean;
  closable: boolean;
}

export type AsamCheckboxButtonEmits = {
    [K in keyof typeof checkboxEmits]: Parameters<(typeof checkboxEmits)[K]>;
};

export type AsamCheckboxButtonProps = Omit<CheckboxPropsPublic, 'size' | 'id' | 'border' | 'indeterminate'> & AsamControlSizeProps & {
    /** 兼容共享 Checkbox 属性；参与内部控件身份计算，但 Button 模板不直接绑定到 input id。 */
    id?: CheckboxPropsPublic['id'];
    /** 兼容共享 Checkbox 属性；Button 不使用此值添加边框，边框由按钮状态与样式决定。 */
    border?: CheckboxPropsPublic['border'];
    /** 兼容共享 Checkbox 属性；Button 不渲染半选样式，部分选择状态请使用 AsamCheckboxItem。 */
    indeterminate?: CheckboxPropsPublic['indeterminate'];
};

export type AsamCheckboxDataEmits<V extends AsamValue = AsamValue, I extends object = object> = Omit<AsamAsyncChoiceEmits<V, I>, 'update:modelValue' | 'change'> & {
    'update:modelValue': [value: readonly V[] | readonly AsamOption<V, I>[] | string];
    change: [value: readonly V[] | readonly AsamOption<V, I>[] | string];
};

export type AsamCheckboxGroupEmits = {
    [K in keyof typeof checkboxGroupEmits]: Parameters<(typeof checkboxGroupEmits)[K]>;
};

export type AsamCheckboxItemEmits = {
    [K in keyof typeof checkboxEmits]: Parameters<(typeof checkboxEmits)[K]>;
};

export type AsamCheckboxProps<V extends AsamValue = AsamValue, I extends object = AsamRecord> = ChoiceOptions<V, I> & Omit<CheckboxGroupPropsPublic, 'modelValue' | 'options' | 'type' | 'props' | 'size'> & {
    type?: 'checkbox' | 'button';
} & ({
    readonly modelValue?: readonly V[];
    readonly valueMode?: 'value';
    readonly multipleValueMode?: 'array';
    readonly separator?: never;
} | {
    readonly modelValue?: string;
    readonly valueMode?: 'value';
    readonly multipleValueMode: 'string';
    readonly separator?: string;
} | {
    readonly modelValue?: readonly AsamChoiceOption<V, I>[];
    readonly valueMode: 'object';
    readonly multipleValueMode?: 'array';
    readonly separator?: never;
});

export type AsamCheckboxPublicComponent = AsamSelectionComponent<AsamCheckboxProps<AsamValue, object>, {
    'update:modelValue': [
        value: AsamCheckboxModelValue<AsamValue, object, 'value' | 'object', 'array' | 'string'>
    ];
    change: [
        value: AsamCheckboxModelValue<AsamValue, object, 'value' | 'object', 'array' | 'string'>
    ];
}, AsamCheckboxSlots, Record<string, never>, true, UnsupportedStaticChoiceSourceProp | 'props'>;

export interface AsamChoiceRuntimeProps extends Omit<CheckboxGroupPropsPublic, 'modelValue' | 'options' | 'type' | 'props' | 'size' | 'disabled' | 'name' | 'id' | 'validateEvent' | 'valueMode' | 'multipleValueMode' | 'separator'>, AsamControlSizeProps {
    readonly modelValue?: unknown;
    readonly options?: readonly AsamChoiceOption<AsamValue, object>[];
    readonly disabled?: boolean;
    readonly name?: string;
    readonly id?: string;
    readonly validateEvent?: boolean;
    readonly valueMode?: 'value' | 'object';
    readonly multipleValueMode?: 'array' | 'string';
    readonly separator?: string;
}

export type AsamClickOutsideDirective = ObjectDirective<HTMLElement, AsamClickOutsideBinding, string, AsamClickOutsideExcludes> & {
    install: (app: App) => void;
};

interface CollapseContext {
  activeNames: Ref<CollapseActiveName[]>;
  handleItemClick: (name: CollapseActiveName) => void;
}

export type AsamColorPickerEmits = {
    [K in keyof typeof colorPickerEmits]: Parameters<(typeof colorPickerEmits)[K]>;
};

export type AsamColorPickerPanelEmits = {
    [K in keyof typeof colorPickerPanelEmits]: Parameters<(typeof colorPickerPanelEmits)[K]>;
};

type ColSizeObject = {
  span?: number;
  offset?: number;
  pull?: number;
  push?: number;
};

export type AsamCompatibleKey<M, R, K extends keyof M> = {
    [C in keyof R]: Same<M[K], Parts<R[C]>['model']> extends true ? C : never;
}[keyof R] & string;

export type AsamComponentProps<P extends object> = Omit<P, AsamReservedControlProp> & {
    readonly [K in AsamReservedControlProp]?: never;
};

export interface AsamConfigProviderSlots {
    default?: (scope: {
        config: ConfigProviderContext | undefined;
    }) => VNode[];
}

export interface AsamControl<M, P extends object, S extends AsamControlSource = never> {
    readonly component: Component;
    readonly emptyValue: () => M;
    readonly sourceKinds: AsamSourceKindTuple<S['kind']>;
    readonly suspendable?: boolean;
    readonly requiredProps?: readonly (keyof P & string)[];
    readonly [asamControlTypes]: {
        readonly model: M;
        readonly props: P;
        readonly source: S;
    };
}

export interface AsamControlDensityTokens {
    height: string;
    buttonPaddingInline: string;
    fontSize: string;
    iconSize: string;
    paddingInline: string;
    gap: string;
    rowPadding: string;
    /** Form spacing; defaults to the shared field gap rather than a native size class. */
    formItemMarginBottom?: string;
}

export type AsamCountdownSlots = InstanceType<typeof ElCountdown>['$slots'] & {
    /** 数值前缀。 */
    prefix?: Slot;
    /** 数值后缀。 */
    suffix?: Slot;
    /** 倒计时标题。 */
    title?: Slot;
};

export interface AsamDataControls<T> {
    readonly reload: (options?: {
        readonly force?: boolean;
    }) => Promise<AsamReloadResult<T>>;
    readonly cancel: () => void;
}

export interface AsamDataError {
    readonly kind: 'config' | 'request' | 'response' | 'transform' | 'upload';
    readonly message: string;
    readonly cause: unknown;
    readonly notified: boolean;
    readonly requestId?: number;
}

export declare class AsamDataFailure extends Error implements AsamDataError {
    readonly kind: AsamDataError['kind'];
    readonly cause: unknown;
    readonly notified = false;
    constructor(kind: AsamDataError['kind'], message: string, cause?: unknown);
}

export interface AsamDataProvider {
    readonly request?: (config: AsamRequestConfig, context: AsamRequestContext) => Promise<unknown>;
    readonly upload?: AsamUploadTransport;
    readonly adaptOptions?: (response: unknown) => readonly AsamRecord[];
    readonly adaptPage?: (response: unknown) => AsamPage<AsamRecord>;
    readonly dict?: AsamDictionaryProvider;
    readonly isErrorNotified?: (cause: unknown) => boolean;
    readonly onError?: (error: AsamDataError) => void;
    readonly pagination?: {
        readonly page: string;
        readonly pageSize: string;
    };
}

export interface AsamDataRuntime {
    readonly provider: AsamDataProvider | undefined;
    readonly scope: string;
    readonly epoch: number;
    install(provider: AsamDataProvider): void;
    setScope(scope: string): void;
    invalidate(): void;
    createContext(): AsamRequestContext;
    isCurrent(context: AsamRequestContext): boolean;
    release(context: AsamRequestContext): void;
    onInvalidate(listener: () => void): () => void;
    reportError(error: AsamDataError, context: AsamRequestContext): AsamDataError;
}

export type AsamDataTableComponent = <Q = AsamRecord, P = unknown, R = unknown, T extends object = AsamRecord>(props: AsamDataTableProps<Q, P, R, T> & AsamDataTableListeners<T> & PublicProps, ctx?: {
    slots: AsamDataTableSlots<T>;
    attrs: Record<string, unknown>;
}, expose?: (value: AsamDataTableExpose<T>) => void) => VNode & {
    __ctx?: {
        props: AsamDataTableProps<Q, P, R, T> & AsamDataTableListeners<T>;
        slots: AsamDataTableSlots<T>;
        expose: (value: AsamDataTableExpose<T>) => void;
    };
};

export interface AsamDataTableEmits<T extends object> extends Omit<AsamTableEmits<T>, 'selection-change'> {
    'update:currentPage': [value: number];
    'update:pageSize': [value: number];
    'page-change': [value: number];
    'page-size-change': [value: number];
    /** Override the base row array with the existing cross-page keys/rows snapshot. */
    'selection-change': [selection: AsamTableSelection<T>];
    success: [data: AsamPage<T>];
    error: [error: AsamDataError];
